mapper.select:
SELECT * FROM ( SELECT p.product_code, p.product_name, p.category, l.lot_no, l.qty, l.status, l.expiry_date, COUNT(h.hold_id) AS active_hold_count, (SELECT MAX(h2.released_at) FROM stock_hold h2 WITH (NOLOCK) WHERE h2.lot_no = l.lot_no) AS last_released_at FROM stock_lot l WITH (NOLOCK) JOIN product p ON p.product_code = l.product_code LEFT JOIN stock_hold h WITH (NOLOCK) ON h.lot_no = l.lot_no AND h.released_at IS NULL WHERE l.status = 'AVAILABLE'
AND p.category = #{category}
AND p.product_code LIKE CONCAT(#{productCode}, '%')
AND YEAR(l.expiry_date) = #{year} AND MONTH(l.expiry_date) = #{month}
GROUP BY p.product_code, p.product_name, p.category, l.lot_no, l.qty, l.status, l.expiry_date UNION ALL SELECT p.product_code, p.product_name, p.category, l.lot_no, l.qty, l.status, l.expiry_date, COUNT(h.hold_id) AS active_hold_count, (SELECT MAX(h2.released_at) FROM stock_hold h2 WITH (NOLOCK) WHERE h2.lot_no = l.lot_no) AS last_released_at FROM stock_lot l WITH (NOLOCK) JOIN product p ON p.product_code = l.product_code LEFT JOIN stock_hold h WITH (NOLOCK) ON h.lot_no = l.lot_no AND h.released_at IS NULL WHERE l.status = 'HOLD'
AND p.category = #{category}
AND p.product_code LIKE CONCAT(#{productCode}, '%')
AND YEAR(l.expiry_date) = #{year} AND MONTH(l.expiry_date) = #{month}
GROUP BY p.product_code, p.product_name, p.category, l.lot_no, l.qty, l.status, l.expiry_date ) t ORDER BY t.category, t.product_code, t.expiry_date, t.lot_no
